import React, { useEffect, useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useSelector } from 'react-redux'
import { selectCurrentUser } from '../features/auth/authSlice'
import SearchBar from '../components/SearchBar'
import SideBar from './SideBar'
import '../styles/header.css'

const Header = () => {
    const user = useSelector(selectCurrentUser)

    const usernameURL = user?.username ? `/${user.username}` : ''
    
    let navLinks
    if (user) {
        navLinks = [
            { text: 'search', linkedTo: user ? `${usernameURL}/search` : '/search' },
            { text: 'contact', linkedTo: user ? `${usernameURL}/contact` : '/contact' },
        ]
    } else {
        navLinks = [
            { text: 'search', linkedTo: `/search` },
            { text: 'contact', linkedTo: `/contact` }
        ]
    }





    return (
        <div className='container-fluid py-3 border-bottom p-0 main-acc'>
            <div className='row position-relative align-items-center justify-content-center container-fluid p-0'>
                

                <div className='col align-items-center justify-content-start bg-primary ps-4 col-4'>
                    <HomeLink user={user} />
                </div>

                <div className='col d-flex align-items-center justify-content-start p-4 d-lg-none'>
                    
                    <i className='fas fa-search' ></i>
                    
                </div>

                <div className='col align-items-center d-lg-block d-flex justify-content-start col-4 d-none'>
                    <SearchBar />
                </div>
                
                <div className='position-absolute w-25 end-0 bg-primary'>
                    <AccountButtons />
                </div>
            </div>

            <div className='container-fluid p-0'>
                <NavLinks navLinks={navLinks} />
            </div>
        </div>
    )
}

const HomeLink = ({ user }) => {
    return (
        <div className='left-child-container'>
            <Link 
            to={`/${user?.username ? user.username : ''}`}
            className='home-link' >
                <div className='fs-4'>
                    Indigenous DB
                </div>
                <div className='fs-6'>
                    Provided By Oyate Learning
                </div>
            </Link>
        </div>
    )
}

const NavLinks = ({navLinks}) => {
    return (
        <div className='lower-container'>
            <div className='nav-links-container'>
                {navLinks.map((link, index) => {
                    return (
                        <NavOption
                            key={index}
                            text={link.text}
                            link={link.linkedTo}
                        />
                    )
                })}
            </div>
        </div>
    )
}

const NavOption = ({ text, link }) => {
    let navigate = useNavigate()

    const handleClick = async (e) => {
        e.preventDefault()
        navigate(link)
    }

    return (
        <label className="content-container" onClick={(e) => handleClick(e)}>
            <p className='content'>{text}</p>
        </label>
    )
}

const AccountButtons = () => {
    let navigate = useNavigate()

    return (
        <div class="button-container-header">
            <button 
            class="button-header button-one-header"
            onClick={() => navigate('/signup')}>
                Sign Up
            </button>
            <a >
                <button class="button-header button-two-header"
                onClick={() => navigate('/login')}>
                    Log In
                </button>
            </a>
        </div>
    )
}


export default Header